    def list_webhooks(
        self,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> List[Dict[str, Any]]:
        """List Webhooks

        Returns all webhooks for the authenticated user.

        Each webhook includes:
        - `url` — The endpoint that receives POST requests
        - `secret` — HMAC-SHA256 signing secret for verifying incoming payloads
        - `events` — List of subscribed event types (empty = all events)
        - `is_active` — Whether the webhook is currently enabled

        **Available event types:**
        - `video.completed` — Fired when a video finishes rendering
        - `video.failed` — Fired when a video render fails
        - `project.created` — Fired when a new project is created
        - `project.updated` — Fired when a project is updated
        - `credit.low` — Fired when credit balance drops below threshold

        ---

        ## Webhook payload structure

        When an event fires, a **POST** request is sent to your URL with:

        **Headers:**
        - `Content-Type: application/json`
        - `X-Webhook-Signature` — HMAC-SHA256 hex digest of the raw request body, signed with your webhook `secret`
        - `X-Webhook-Event` — The event type string (e.g. `video.completed`)

        **Body format:** Every webhook POST body is a JSON object with two top-level keys:

        | Field | Type | Description |
        | ----- | ---- | ----------- |
        | `event` | string | The event type (e.g. `video.completed`) |
        | `data` | object | Event-specific payload (see below) |

        ---

        ### `video.completed`

        Fired when a video finishes rendering successfully.

        | `data` field | Type | Description |
        | ------------ | ---- | ----------- |
        | `task_id` | string | The task ID returned when the video was submitted |
        | `video_type` | string | One of: `idea`, `script`, `blog`, `audio`, `translate` |
        | `video_url` | string | Public download URL for the rendered video (MP4) |

        ```json
        {
          "event": "video.completed",
          "data": {
            "task_id": "a1b2c3d4e5f6",
            "video_type": "idea",
            "video_url": "https://storage.zebracat.ai/renders/final.mp4"
          }
        }
        ```

        ### `video.failed`

        Fired when video generation or rendering fails.

        | `data` field | Type | Description |
        | ------------ | ---- | ----------- |
        | `task_id` | string | The task ID returned when the video was submitted |
        | `video_type` | string | One of: `idea`, `script`, `blog`, `audio`, `translate` |
        | `error` | string | Human-readable error description |

        ```json
        {
          "event": "video.failed",
          "data": {
            "task_id": "a1b2c3d4e5f6",
            "video_type": "idea",
            "error": "Rendering timed out after 30 minutes"
          }
        }
        ```

        ### `project.created`

        Fired when a new project is created (e.g. via a video generation request).

        | `data` field | Type | Description |
        | ------------ | ---- | ----------- |
        | `project_id` | integer | The project ID |
        | `name` | string | Project name |
        | `video_type` | string | The video type used |

        ### `project.updated`

        Fired when a project is updated.

        | `data` field | Type | Description |
        | ------------ | ---- | ----------- |
        | `project_id` | integer | The project ID |
        | `name` | string | Project name |

        ### `credit.low`

        Fired when your API dollar balance drops below the low-balance threshold.

        | `data` field | Type | Description |
        | ------------ | ---- | ----------- |
        | `dollar_balance` | string | Current remaining balance (e.g. `"2.50"`) |

        ---

        ## Signature verification

        Every webhook request includes an `X-Webhook-Signature` header. Verify it to ensure the request came from Zebracat:

        ```python
        import hmac, hashlib

        expected = hmac.new(
            webhook_secret.encode(),
            request.body,  # raw bytes
            hashlib.sha256,
        ).hexdigest()

        if not hmac.compare_digest(expected, request.headers['X-Webhook-Signature']):
            return HttpResponse(status=403)
        ```

        ``GET /api/v1/public/webhooks``
        """
        return self._request(
            OPERATIONS["list_webhooks"],
            path={},
            query={},
            body=None,
            idempotency_key=None,
            request_options=request_options,
        )

    def create_webhook(
        self,
        *,
        url: str,
        name: Union[str, NotGiven] = NOT_GIVEN,
        events: Union[List[Literal["video.completed", "video.failed", "project.created", "project.updated", "credit.low", "video.plan_ready", "video.needs_input", "video.generating", "studio.job.completed", "studio.job.failed", "character_swap.completed", "character_swap.failed"]], NotGiven] = NOT_GIVEN,
        extra_body: Optional[Dict[str, Any]] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> Dict[str, Any]:
        """Create Webhook

        Register a new webhook endpoint.

        A unique `secret` (format `whsec-...`) is generated automatically and returned in the response. Use this secret to verify incoming webhook payloads via HMAC-SHA256 signature in the `X-Webhook-Signature` header. The webhook starts enabled (`is_active=true`).

        **Request body:**
        - `url` *(required)* — The HTTPS endpoint that will receive event POSTs (max 500 chars)
        - `name` *(optional)* — A label for this webhook (e.g. `Production`, `Staging`). Defaults to an empty string.
        - `events` *(optional)* — List of event types to subscribe to. If omitted or empty (the default), the webhook receives **all** events. Each entry must be one of the allowed values below.

        **Available event types:**
        - `video.completed` — Fired when a video finishes rendering
        - `video.failed` — Fired when a video render fails
        - `project.created` — Fired when a new project is created
        - `project.updated` — Fired when a project is updated
        - `credit.low` — Fired when credit balance drops below threshold

        ``POST /api/v1/public/webhooks``
        """
        body = {"url": url, "name": name, "events": events}
        if extra_body:
            body.update(extra_body)
        return self._request(
            OPERATIONS["create_webhook"],
            path={},
            query={},
            body=body,
            idempotency_key=None,
            request_options=request_options,
        )

    def get_webhook(
        self,
        webhook_id: int,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> Dict[str, Any]:
        """Get Webhook

        Retrieve details of a single webhook owned by the authenticated user, looked up by its numeric `webhook_id` (path parameter). The response includes the signing `secret`. Returns 404 if the webhook does not exist or belongs to another user.

        ``GET /api/v1/public/webhooks/{webhook_id}``
        """
        return self._request(
            OPERATIONS["get_webhook"],
            path={"webhook_id": webhook_id},
            query={},
            body=None,
            idempotency_key=None,
            request_options=request_options,
        )

    def update_webhook(
        self,
        webhook_id: int,
        *,
        url: Union[str, NotGiven] = NOT_GIVEN,
        name: Union[str, NotGiven] = NOT_GIVEN,
        events: Union[List[EventsEnum], NotGiven] = NOT_GIVEN,
        is_active: Union[bool, NotGiven] = NOT_GIVEN,
        rotate_secret: Union[bool, NotGiven] = NOT_GIVEN,
        extra_body: Optional[Dict[str, Any]] = None,
        request_options: Optional[RequestOptions] = None,
    ) -> Dict[str, Any]:
        """Update Webhook

        Change a webhook: `url` (public https), `name`, `events`, `is_active` (false pauses deliveries), or `rotate_secret: true` for a new signing secret (the answer carries it; the old one stops at once). Fields left out keep their value.

        ``PATCH /api/v1/public/webhooks/{webhook_id}``
        """
        body = {"url": url, "name": name, "events": events, "is_active": is_active, "rotate_secret": rotate_secret}
        if extra_body:
            body.update(extra_body)
        return self._request(
            OPERATIONS["update_webhook"],
            path={"webhook_id": webhook_id},
            query={},
            body=body,
            idempotency_key=None,
            request_options=request_options,
        )

    def delete_webhook(
        self,
        webhook_id: int,
        *,
        request_options: Optional[RequestOptions] = None,
    ) -> None:
        """Delete Webhook

        Permanently delete the webhook identified by its numeric `webhook_id` (path parameter). Unlike API keys, webhooks are hard-deleted — this action cannot be undone and no further events will be delivered to its URL. Returns an empty `204 No Content` body on success.

        ``DELETE /api/v1/public/webhooks/{webhook_id}``
        """
        return self._request(
            OPERATIONS["delete_webhook"],
            path={"webhook_id": webhook_id},
            query={},
            body=None,
            idempotency_key=None,
            request_options=request_options,
        )


